argv:
($o, $n, $all, $f) = @ARGV;
open(my $in, "<", $f) or die "cannot read $f: $!\n";
local $/; my $s = <$in>; close $in;
my $c = () = $s =~ /\Q$o\E/g;
die "old_string not found in $f\n" if $c == 0;
die "old_string is not unique in $f ($c matches); add context or pass replace_all\n"
  if $c > 1 && $all ne "true";
if ($all eq "true") { $s =~ s/\Q$o\E/$n/g } else { $s =~ s/\Q$o\E/$n/ }
open(my $out, ">", $f) or die "cannot write $f: $!\n";
print $out $s; close $out;
print "edited $f ($c replacement", ($c == 1 ? "" : "s"), ")\n";
